const STASpecialQueries = { ObsLayer: { description: {cat: "Capa d'Observations", spa: "Capa de Observations", eng: "Observations Layer"}, query: "Observations?$orderby=phenomenonTime%20desc&$expand=Datastream($select=unitOfMeasurement),Datastream/ObservedProperty($select=name,description,definition),FeatureOfInterest($select=description,feature)&$select=phenomenonTime,result", help: {cat: "Enllaç al servei STAplus per afegir una consulta a aquest URL i obtenir una taula amb phenomenomTime i els resultats de les Observations, les unitsOfMeasurements i l'ObservedProperty dels Datastreams i una descripció del featureOfInterest relacionat.", spa: "Enlace al servicio STAplus para añadir una consulta a esta URL y obtener una tabla con phenomenomTime y los resultados de las Observations, las unitsOfMeasurements y la ObservedProperty de los Datastreams y una descripción del featureOfInterest relacionado.", eng: "Link to STAplus service to add a query to this url to obtain a table with phenomenomTime and results from Observations, unitsOfMeasurements and ObservedProperty from Datastreams and a description from the featureOfInterest related."} } };
