const STAOperations = {
	RecursiveExpandSTA: { description: {cat: "Expansió recursiva", spa: "Expansión recursiva", eng: "Recursive Expand"}, callSTALoad: true, addSTAQuery: true, help: {cat: "Obté una taula seleccionant algunes columnes i afegint columnes que resulten d'expandir les propietats de les entitats enllaçades de manera recursiva. Cal que estigui connectat a un node SensorThings API o STAplus.", spa: "Se obtiene una tabla seleccionando algunas columnas y añadiendo columnas que resultan de expandir las propiedades de las entidades vinculadas de forma recursiva. Requiere estar conectado a un nodo SensorThings API o STAplus.", eng: "Gets a table by selecting some columns and adding columns by expanding the properties of linked entities recursively. Needs to be connected to a SensorThings API or a STAplus node."} },
	ExpandColumnSTA: { description: {cat: "Expandeix l'entitat", spa: "Expande la entidad", eng: "Expand entity"}, callSTALoad: true, addSTAQuery: true, help: {cat: "S' obté una taula afegint columnes que resulten de l'expansió de les propietats d'una entitat enllaçada. Per exemple, en un Datastream, afegeix les propietats d'ObservedProperties. Cal que estigui connectat a un node SensorThings API o STAplus.", spa: "Se obtiene una tabla añadiendo columnas que resultan de la expansión de las propiedades de una entidad vinculada. Por ejemplo, en un Datastream, añade las propiedades de ObservedProperties. Requiere estar conectado a un nodo SensorThings API o STAplus.", eng: "Gets a table by adding columns resulting of the expansion of the properties of a linked entity. For example, in a Datastream add properties of ObservedProperties. Requeres to be connected to a SensorThings API or a STAplus node."} },
	MergeExpandsSTA: { description: {cat: "Fusiona les expansions", spa: "Fusiona las expansiones", eng: "Merge Expands"}, callSTALoad: true, addSTAQuery: true, help: {cat: "S'obté una taula fusionant els camps de dues branques originades com a expansió de la mateixa entitat. Per exemple, en un node Datastream, una branca iniciada expandint les propietats d'ObservedProperties i una branca iniciada expandint les propietats de Thing es poden fusionar en una sola branca connectant les dues branques com a entrades d'aquest node.", spa: "Se obtiene una tabla fusionando los campos de dos ramas originadas como expansión de la misma entidad. Por ejemplo, en un nodo Datastream, una rama iniciada expandiendo las propiedades de ObservedProperties y una rama iniciada expandiendo las propiedades de Thing se pueden fusionar en una sola rama conectando ambas ramas como entradas de este nodo.", eng: "Gets a table by merging the fields of two branches originated as an expansion of the same entity. For example, in a Datastream node, a branch started by expanding ObservedProperties properties and a branch started by expanding Thing properties can be merged in a single branch by connecting the two branches as inputs to this node."} },
	SelectColumnsSTA: { description: {cat: "Selecciona columnes", spa: "Selecciona columnas", eng: "Select Columns"}, callSTALoad: true, addSTAQuery: true, help: {cat: "S'obté una taula només amb les columnes seleccionades. Cal que estigui connectat a un node SensorThings API o STAplus.", spa: "Se obtiene una tabla solo con las columnas seleccionadas. Requiere que esté conectado a un nodo SensorThings API o STAplus.", eng: "Gets a table only with columns selected. Requeres to be connected to a SensorThings API or a STAplus node."} },
	SelectRowSTA: { description: {cat: "Selecciona una fila", spa: "Selecciona una fila", eng: "Select Row"}, callSTALoad: true, help: {cat: "S'obté una taula només amb el registre seleccionat. Cal que estigui connectat a una altra entitat SensorThings API o STAplus. És necessari un únic registre per relacionar altres entitats amb aquesta i navegar pel model de dades de SensorThings API o STAplus.", spa: "Se obtiene una tabla solo con el registro seleccionado. Requiere estar conectado a otra entidad SensorThings API o STAplus. Se necesita un único registro para relacionar otras entidades con esta y navegar por el modelo de datos de SensorThings API o STAplus.", eng: "Gets a table only with the selected record. Requeres to be connected to another SensorThings API or a STAplus entity. A single record is required to related entities to this one and navegate the SensorThings API or a STAplus data model."} },
	SelectResourceSTA: { description: {cat: "Selecciona un registre", spa: "Seleccionar un registro", eng: "Select Resource"}, callSTALoad: true, help: {cat: "S'obté una taula només amb el recurs seleccionat. Cal que estigui connectat a una altra entitat SensorThings API o STAplus. És necessari un únic registre per relacionar altres entitats amb aquesta i navegar pel model de dades de SensorThings API o STAplus.", spa: "Se obtiene una tabla solo con el recurso seleccionado. Requiere estar conectado a otra entidad SensorThings API o STAplus. Se necesita un único registro para relacionar otras entidades con esta y navegar por el modelo de datos de SensorThings API o STAplus.", eng: "Gets a table only with the selected resource. Requeres to be connected to another SensorThings API or a STAplus entity. A single record is required to related entities to this one and navegate the SensorThings API or a STAplus data model."} },
	FilterRowsSTA: { description: {cat: "Filtra les files", spa: "Filtra las filas", eng: "Filter Rows"}, callSTALoad: true, addSTAQuery: true, help: {cat: "S'obté una taula amb els registres que compleixen les condicions seleccionades. Requereix una connexió a un node SensorThings API o STAplus. Feu doble clic per obrir el diàleg de filtre.", spa: "Se obtiene una tabla con los registros que cumplen las condiciones seleccionadas. Requiere una conexión a un nodo SensorThings API o STAplus. Haga doble clic para abrir el diálogo de filtro.", eng: "Gets a table with the records that match your conditions. Requires a connection to a SensorThings API or STAplus node. Double-click to open the filter dialog."} },
	FilterRowsByTime: { description: {cat: "Filtra les files per temps", spa: "Filtra las filas por tiempo", eng: "Filter Rows by time"}, addSTAQuery: true, help: {cat: "S'obté una taula amb els registres que coincideixen amb un interval de temps determinat. És possible agrupar-los per períodes de temps. Cal que estigui connectat a un node SensorThings API o STAplus.", spa: "Se obtiene una tabla con los registros que coinciden con un intervalo de tiempo seleccionado. Es posible agruparlos por períodos de tiempo. Requiere estar conectado a un nodo SensorThings API o STAplus.", eng: "Gets a table with records that match with a time interval. It is possible to group them by time periods. Requeres to be connected to a SensorThings API or a STAplus node."} },
	GeoFilterPolSTA: { description: {cat: "Filtra les files per polígon", spa: "Filtrar las filas por polígono", eng: "Filter Rows by Polygon"}, addSTAQuery: true, callSTALoad: true, help: {cat: "S'obté una taula amb els registres continguts dins d'un polígon. Cal que estigui connectat a una altra entitat SensorThings API o STAplus i a una taula amb un registre que tingui una geometria (polígon).", spa: "Se obtiene una tabla con los registros contenidos dentro de un polígono. Requiere estar conectado a otra entidad SensorThings API o STAplus y a una tabla con un registro que tenga una geometría (polígono).", eng: "Gets a table with the records within a polygon. Requeres to be connected to another SensorThings API or a STAplus entity and to a table with a record that has a geometry (polygon)."} },
	GeoFilterPntSTA: { description: {cat: "Filtra les files per distància", spa: "Filtrar las filas por distancia", eng: "Filter Rows by Distance"}, addSTAQuery: true, callSTALoad: true, help: {cat: "S'obté una taula amb els registres que es troben a una distància inferior a una distància donada respecte d'un punt. Cal que estigui connectat a un node SensorThings API o STAplus.", spa: "Se obtiene una tabla con los registros que se encuentran a una distancia inferior a una distancia dada respecto de un punto. Requiere estar conectado a un nodo SensorThings API o STAplus.", eng: "Gets a table with the records that are closer that a given distance of a point. Requeres to be connected to a SensorThings API or a STAplus node."} },
	SortBySTA: { description: {cat: "Ordena per", spa: "Ordenar por", eng: "Sort by"}, callSTALoad: true, addSTAQuery: true, help: {cat: "S'obté una taula amb les dades ordenades segons un criteri determinat. Cal que estigui connectat a un node SensorThings API o STAplus.", spa: "Se obtiene una tabla con los datos ordenados según un criterio determinado. Requiere estar conectado a un nodo SensorThings API o STAplus.", eng: "Gets a table with data sorted by a given criteria. Requeres to be connected to a SensorThings API or a STAplus node."} },
	RangeSTA: { description: {cat: "Interval de registres", spa: "Intervalo de registros", eng: "Record range"}, callSTALoad: true, addSTAQuery: true, help: {cat: "S'obté una taula amb un subconjunt dels registres limitant el nombre de registres i ometent-ne alguns d'inicials. <hr><small>Implementa $top i $skip. Cal que estigui connectat a un node SensorThings API o STAplus</small>.", spa: "Obtiene una tabla con un subconjunto de los registros limitando el número de registros y omitiendo algunos iniciales. <hr><small>Implementa $top y $skip. Requiere estar conectado a un nodo SensorThings API o STAplus</small>.", eng: "Gets a table with a subset of the records limiting the number of records and skiping some initial records. <hr><small>Implements $top and $skip. Requeres to be connected to a SensorThings API or a STAplus node</small>."} },
	UploadObservations: { description: {cat: "Puja a STA", spa: "Subir a STA", eng: "Upload in STA"}, leafNode: true, help: {cat: "Desa algunes observacions en un servidor SensorThings API o STAplus.", spa: "Guarda algunas observaciones en un servidor SensorThings API o STAplus.", eng: "Saves some observations to a SensorThings API or a STAplus server."} },
	CalculateStatisticsSTA: { description: {cat: "Puja les estadístiques a STA", spa: "Subir estadísticas a STA", eng: "Upload statistics in STA"}, leafNode: true, help: {cat: "Desa les estadístiques d'Observations a un servidor SensorThings API o STAplus.", spa: "Guarda las estadísticas de Observations en un servidor SensorThings API o STAplus.", eng: "Saves statistics of Observations in SensorThings API or a STAplus server."} },
	//UploadTimeAverages: {description: "Upload time averages", leafNode: true},
	CountResultsSTA: { description: {cat: "Compta els resultats", spa: "Conta los resultados", eng: "Count results"}, leafNode: true, help: {cat: "Retorna el nombre total de registres que retorna la consulta a l'API sense carregar-los en una taula. Només amb dades STA. Cal que estigui connectat a un node d'entitat SensorThings API o STAplus. Aquest node no es pot connectar a altres nodes dependents.", spa: "Devuelve el número total de registros que devuelve la consulta a la API sin cargarlos en una tabla. Solo con datos STA. Requiere estar conectado a un nodo de entidad SensorThings API o STAplus. Este nodo no puede conectarse a otros nodos dependientes.", eng: "Returns the total number of records returned by the API query without loading them in a table. Only with STA data. Requeres to be connected to a SensorThings API or a STAplus entity node. This node can not be connected to other dependend nodes."} },
	ViewQuerySTA: { description: {cat: "Visualitza la consulta", spa: "Ver la consulta", eng: "View Query"}, leafNode: true, help: {cat: "Mostra en un quadre de diàleg l'URL complet que s'utilitza per fer la consulta per obtenir les dades d'un servei o d'una API del node dependent. Com que l'URL que hi ha darrere del node actiu sempre es representa a l'àrea de consulta i de taula, l'ús d'aquesta operació ja no és recomanable.", spa: "Muestra en un cuadro de diálogo la URL completa que se utiliza para hacer la consulta para obtener los datos de un servicio o de una API del nodo dependiente. Dado que la URL que hay detrás del nodo activo siempre se representa en el área de consulta y de tabla, el uso de esta operación ya no es recomendable.", eng: "Shows the completed URL that is used to make the query to obtain the data from a service or an API of the depended node in a dialog box. Since the URL behind the active node is always represented in the query and table area, the use of this operation is no longer recommended."} },
	OneValueSTA: { description: {cat: "Un valor", spa: "Un valor", eng: "One Value"}, leafNode: true, help: {cat: "Mostra l'últim valor publicat. Aquest valor s'actualitza segons el període de temps que s'estableixi. Cal que estigui connectat a una altra entitat SensorThings API o STAplus. Si WebSub està disponible, se subscriu a un tema, obre una connexió websocket i espera actualitzacions; si no, genera una petició HTTP cada n segons. No cal connectar-lo a una eina d'ordenació temporal. Aquest node no es pot connectar a altres nodes dependents.", spa: "Muestra el último valor publicado. Este valor se actualiza según el período de tiempo que se establezca. Requiere estar conectado a otra entidad SensorThings API o STAplus. Si WebSub está disponible, se suscribe a un tema, abre una conexión websocket y espera actualizaciones; si no, genera una solicitud HTTP cada n segundos. No es necesario conectarlo a una herramienta de ordenación temporal. Este nodo no puede conectarse a otros nodos dependientes.", eng: "Shows the last posted value. This value is updated according to the time period you set. Requeres to be connected to another SensorThings API or a STAplus entity. If WebSub available, it subscribes to a topic, opens a websocket connection and waits for updates, if not, it generates a HTTP request every n seconds. Do not requre to connect to previous sort by time. This node can not be connected to other dependend nodes."} },
	SubscribeSTA: { description: {cat: "Subscripció i alerta", spa: "Suscripción y alerta", eng: "Subscribe and alert"}, help: {cat: "Se subscriu a les notificacions de canvi del recurs pare. Cal que el node pare sigui un STA o un STAplus amb WebSub disponible. Després se subscriu a un tema, obre una connexió websocket i espera actualitzacions. Quan es reben registres nous, s'afegeixen immediatament a la taula.", spa: "Se suscribe a las notificaciones de cambio del recurso padre. Requiere que el nodo padre sea un STA o un STAplus con WebSub disponible. Luego se suscribe a un tema, abre una conexión websocket y espera actualizaciones. Cuando se reciben registros nuevos, se añaden inmediatamente a la tabla.", eng: "Subscribes to notifications of change in the parent resource. It requires that the parent node is a STA or STAplus with WebSub available. Then it subscribes to a topic and opens a websocket connection and waits for updates. When new records are received, they are immediately added to the table."} }
};
